const items = $input.all();

function normalizarNumero(valor) {
  if (typeof valor === 'number') return valor;

  let texto = String(valor ?? '').trim();

  // Formato brasileiro: R$ 12.500,00 -> 12500
  texto = texto
    .replace(/R\$\s?/gi, '')
    .replace(/\s/g, '')
    .replace(/\./g, '')
    .replace(',', '.');

  const numero = Number(texto);

  return Number.isFinite(numero) ? numero : null;
}

function analisarCSV(texto) {
  // Leitor simples que respeita campos entre aspas e vírgulas
  const linhas = texto
    .replace(/^\uFEFF/, '')
    .split(/\r?\n/)
    .filter(linha => linha.trim() !== '');

  if (linhas.length < 2) return [];

  function separarLinha(linha) {
    const resultado = [];
    let campo = '';
    let aspas = false;

    for (let i = 0; i < linha.length; i++) {
      const caractere = linha[i];

      if (caractere === '"') {
        if (aspas && linha[i + 1] === '"') {
          campo += '"';
          i++;
        } else {
          aspas = !aspas;
        }
      } else if (caractere === ',' && !aspas) {
        resultado.push(campo.trim());
        campo = '';
      } else {
        campo += caractere;
      }
    }

    resultado.push(campo.trim());
    return resultado;
  }

  const cabecalhos = separarLinha(linhas[0]).map(c =>
    c.replace(/^\uFEFF/, '').trim().toLowerCase()
  );

  return linhas.slice(1).map(linha => {
    const valores = separarLinha(linha);
    const registro = {};

    cabecalhos.forEach((cabecalho, indice) => {
      registro[cabecalho] = valores[indice] ?? '';
    });

    // Normaliza colunas comuns de valor/saldo
    for (const chave of Object.keys(registro)) {
      if (/saldo|valor|balance|amount/i.test(chave)) {
        registro[chave] = normalizarNumero(registro[chave]);
      }
    }

    return registro;
  });
}

return items.flatMap(item => {
  const dados = item.json;

  // O HTTP Request pode entregar o CSV em diferentes propriedades.
  const csv = typeof dados === 'string'
    ? dados
    : dados.body ?? dados.data ?? dados.csv ?? dados.response ?? null;

  if (typeof csv !== 'string') {
    throw new Error(
      'CSV não encontrado como texto. Verifique a saída do HTTP Request e ajuste a propriedade dados.body, dados.data ou dados.csv.'
    );
  }

  const registros = analisarCSV(csv);

  return registros.map(registro => ({ json: registro }));
});

/**
 * DESAFIO DIO - AUTOMAÇÃO DE INVESTIMENTOS COM N8N
 * Objetivo: gerar mensagens personalizadas conforme o perfil
 * de investimento de cada cliente.
 */

// Recebe os dados de entrada do node anterior
const entradas = $input.all();

// Converte saldo em texto para número, se necessário
function converterSaldo(valor) {
  if (typeof valor === "number") {
    return valor;
  }

  if (!valor) {
    return 0;
  }

  const numero = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .trim();

  return Number(numero) || 0;
}

// Formata o saldo em reais
function formatarSaldo(valor) {
  return valor.toLocaleString("pt-BR", {
    style: "currency",
    currency: "BRL"
  });
}

// Cria uma orientação educativa conforme o perfil
function gerarOrientacao(perfil, nome, saldo) {
  const perfilNormalizado = String(perfil || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim();

  let mensagem;
  let caracteristicas;
  let exemplos;
  let cuidados;

  if (perfilNormalizado.includes("conservador")) {
    caracteristicas =
      "Você tende a priorizar a segurança do dinheiro e a estabilidade, " +
      "aceitando menor potencial de retorno em troca de menor oscilação.";

    exemplos =
      "Como exemplos para estudar, existem o Tesouro Selic e CDBs " +
      "de instituições financeiras cobertos pelo FGC, observadas as regras e os limites da garantia.";

    cuidados =
      "Antes de investir, confira liquidez, taxas, tributação, prazo e riscos. " +
      "Mantenha uma reserva de emergência acessível.";

    mensagem =
      `Olá, ${nome}! Considerando seu perfil conservador e seu saldo de ` +
      `${formatarSaldo(saldo)}, vale priorizar o estudo de alternativas ` +
      `que busquem preservar seu dinheiro e ofereçam previsibilidade. ` +
      `${caracteristicas} ${exemplos} ${cuidados} ` +
      `Esta é uma orientação educativa, não uma recomendação financeira individual.`;

  } else if (perfilNormalizado.includes("moderado")) {
    caracteristicas =
      "Você pode buscar equilíbrio entre segurança e crescimento, " +
      "considerando que alguns investimentos apresentam oscilações.";

    exemplos =
      "Para estudar, compare opções de renda fixa, como Tesouro Direto e CDBs, " +
      "com alternativas diversificadas de maior risco, de acordo com seus objetivos e prazo.";

    cuidados =
      "Avalie a diversificação, a liquidez, as taxas e sua capacidade de suportar perdas. " +
      "Não invista em ativos voláteis o dinheiro necessário no curto prazo.";

    mensagem =
      `Olá, ${nome}! Com seu perfil moderado e saldo de ` +
      `${formatarSaldo(saldo)}, você pode estudar estratégias que equilibrem ` +
      `estabilidade e potencial de crescimento. ${caracteristicas} ` +
      `${exemplos} ${cuidados} ` +
      `Esta é uma orientação educativa, não uma recomendação financeira individual.`;

  } else if (perfilNormalizado.includes("arrojado")) {
    caracteristicas =
      "Você demonstra maior disposição para aceitar oscilações em busca de crescimento, " +
      "mas isso não elimina o risco de perdas.";

    exemplos =
      "Como temas de estudo, considere a diversificação entre renda fixa e renda variável, " +
      "incluindo fundos de índice (ETFs) e ações, sempre compreendendo os riscos de cada ativo.";

    cuidados =
      "Considere seu horizonte de longo prazo, diversifique e evite concentrar " +
      "todo o dinheiro em um único ativo. Retornos não são garantidos.";

    mensagem =
      `Olá, ${nome}! Considerando seu perfil arrojado e seu saldo de ` +
      `${formatarSaldo(saldo)}, vale estudar estratégias diversificadas ` +
      `com potencial de crescimento no longo prazo. ${caracteristicas} ` +
      `${exemplos} ${cuidados} ` +
      `Esta é uma orientação educativa, não uma recomendação financeira individual.`;

  } else {
    mensagem =
      `Olá, ${nome}! Recebemos seu saldo de ${formatarSaldo(saldo)}, ` +
      `mas não identificamos seu perfil de investimento. ` +
      `Antes de estudar alternativas, procure definir seus objetivos, ` +
      `prazo, necessidade de liquidez e tolerância a riscos.`;
  }

  return mensagem;
}

// Processa cada cliente, inclusive quando todos chegam
// dentro de um único array chamado "clientes".
const clientes = [];

for (const item of entradas) {
  const dados = item.json;

  if (Array.isArray(dados.clientes)) {
    clientes.push(...dados.clientes);
  } else if (Array.isArray(dados.body?.clientes)) {
    clientes.push(...dados.body.clientes);
  } else {
    clientes.push(dados);
  }
}

// Gera um item de saída para cada cliente
return clientes.map((cliente) => {
  const nome = cliente.nome || "Cliente";
  const email = cliente.email || "";
  const saldo = converterSaldo(cliente.saldo);
  const perfil = cliente.perfil || "Não informado";

  const mensagem = gerarOrientacao(perfil, nome, saldo);

  return {
    json: {
      nome,
      email,
      saldo: formatarSaldo(saldo),
      perfil,
      mensagem
    }
  };
});

/**
 * DESAFIO DIO - RELATÓRIO DE CLIENTES
 * Organiza os dados em tabela com HTML e resumo em JSON.
 */

const entradas = $input.all();

// Escapa caracteres especiais para evitar problemas no HTML
function escaparHTML(valor) {
  return String(valor ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

// Formata valores monetários
function formatarSaldo(valor) {
  if (typeof valor === "number") {
    return valor.toLocaleString("pt-BR", {
      style: "currency",
      currency: "BRL"
    });
  }

  const texto = String(valor ?? "R$ 0,00").trim();

  // Mantém valores que já estão formatados em reais
  if (texto.includes("R$")) {
    return texto;
  }

  const numero = Number(
    texto.replace(/\./g, "").replace(",", ".")
  );

  return Number.isFinite(numero)
    ? numero.toLocaleString("pt-BR", {
        style: "currency",
        currency: "BRL"
      })
    : texto;
}

// Aceita itens individuais ou uma lista dentro de "clientes"
const clientes = [];

for (const item of entradas) {
  const dados = item.json;

  if (Array.isArray(dados.clientes)) {
    clientes.push(...dados.clientes);
  } else if (Array.isArray(dados.body?.clientes)) {
    clientes.push(...dados.body.clientes);
  } else {
    clientes.push(dados);
  }
}

// Prepara os dados de cada cliente
const relatorio = clientes.map((cliente, indice) => ({
  numero: indice + 1,
  nome: cliente.nome || "Não informado",
  email: cliente.email || "Não informado",
  perfil: cliente.perfil || "Não informado",
  saldo: formatarSaldo(
    cliente.saldo ?? cliente.saldoFormatado ?? 0
  ),
  mensagem: cliente.mensagem || "Mensagem não disponível"
}));

// Cria as linhas da tabela HTML
const linhasHTML = relatorio.map(cliente => `
  <tr>
    <td>${cliente.numero}</td>
    <td>${escaparHTML(cliente.nome)}</td>
    <td>${escaparHTML(cliente.email)}</td>
    <td>${escaparHTML(cliente.perfil)}</td>
    <td>${escaparHTML(cliente.saldo)}</td>
    <td>${escaparHTML(cliente.mensagem)}</td>
  </tr>
`).join("");

// Monta o relatório completo
const html = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Relatório de Clientes</title>
  <style>
    body {
      font-family: Arial, sans-serif;
      color: #222;
      margin: 24px;
    }
    h1 {
      color: #17365d;
      text-align: center;
    }
    .resumo {
      margin: 20px 0;
      padding: 15px;
      background: #f1f5f9;
      border-radius: 8px;
    }
    .tabela-container {
      overflow-x: auto;
    }
    table {
      width: 100%;
      border-collapse: collapse;
      font-size: 14px;
    }
    th, td {
      border: 1px solid #d1d5db;
      padding: 10px;
      text-align: left;
      vertical-align: top;
    }
    th {
      background: #17365d;
      color: white;
    }
    tbody tr:nth-child(even) {
      background: #f8fafc;
    }
    td:last-child {
      min-width: 320px;
      line-height: 1.5;
    }
  </style>
</head>
<body>
  <h1>Relatório de Clientes e Perfis de Investimento</h1>

  <div class="resumo">
    <strong>Total de clientes:</strong> ${relatorio.length}
  </div>

  <div class="tabela-container">
    <table>
      <thead>
        <tr>
          <th>Nº</th>
          <th>Nome</th>
          <th>E-mail</th>
          <th>Tipo de investidor</th>
          <th>Saldo</th>
          <th>Mensagem personalizada</th>
        </tr>
      </thead>
      <tbody>
        ${linhasHTML}
      </tbody>
    </table>
  </div>
</body>
</html>
`;

// Retorna um item contendo o relatório organizado
return [{
  json: {
    titulo: "Relatório de Clientes",
    totalClientes: relatorio.length,
    clientes: relatorio,
    tabelaHTML: html
  }
}];

/**
 * DIO - RELATÓRIO DE E-MAILS
 * Gera uma tabela HTML e prepara um item por cliente para o Gmail.
 */

const entradas = $input.all();

function escaparHTML(valor) {
  return String(valor ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function obterTexto(dados) {
  const possiveis = [
    dados.body,
    dados.mensagem,
    dados.text,
    dados.output_text,
    dados.message?.content,
    dados.response?.text
  ];

  const valor = possiveis.find(v => v !== undefined && v !== null);

  if (typeof valor === "string") return valor.trim();

  if (Array.isArray(valor)) {
    return valor.map(p =>
      typeof p === "string" ? p : p.text ?? p.content ?? ""
    ).join("\n").trim();
  }

  if (valor && typeof valor === "object") {
    return valor.text ?? valor.content ?? JSON.stringify(valor);
  }

  return "";
}

function formatarSaldo(valor) {
  if (typeof valor === "number") {
    return valor.toLocaleString("pt-BR", {
      style: "currency",
      currency: "BRL"
    });
  }

  return String(valor ?? "Não informado");
}

// Cada entrada deve representar um cliente.
// Se os clientes estiverem dentro de um array, separa-os.
const clientes = [];

for (const item of entradas) {
  const dados = item.json;

  if (Array.isArray(dados.clientes)) {
    clientes.push(...dados.clientes);
  } else if (Array.isArray(dados.body?.clientes)) {
    clientes.push(...dados.body.clientes);
  } else {
    clientes.push(dados);
  }
}

// Padroniza os campos para o Gmail
const emails = clientes.map((cliente, indice) => {
  const nome = cliente.nome || "Cliente";
  const to = String(cliente.to ?? cliente.email ?? "").trim();
  const perfil = cliente.perfil || "Não informado";
  const saldo = formatarSaldo(cliente.saldo ?? cliente.saldoFormatado);

  const body = obterTexto(cliente);

  const subject = cliente.subject ||
    `Orientações educativas de investimento - ${nome}`;

  const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(to);

  return {
    numero: indice + 1,
    nome,
    to,
    perfil,
    saldo,
    subject,
    body,
    emailValido,
    prontoParaEnvio: emailValido && body.length > 0
  };
});

// Constrói a tabela HTML
const linhas = emails.map(e => `
  <tr>
    <td>${e.numero}</td>
    <td>${escaparHTML(e.nome)}</td>
    <td>${escaparHTML(e.to)}</td>
    <td>${escaparHTML(e.perfil)}</td>
    <td>${escaparHTML(e.saldo)}</td>
    <td>${escaparHTML(e.subject)}</td>
    <td>${escaparHTML(e.body || "Mensagem não encontrada")}</td>
    <td>${e.prontoParaEnvio ? "Pronto para envio" : "Revisar"}</td>
  </tr>
`).join("");

const tabelaHTML = `
<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<title>Relatório de e-mails dos clientes</title>
<style>
  body { font-family: Arial, sans-serif; margin: 20px; color: #222; }
  h1 { color: #17365d; }
  .resumo { padding: 12px; background: #eef3f8; margin-bottom: 16px; }
  .tabela { overflow-x: auto; }
  table { width: 100%; border-collapse: collapse; font-size: 13px; }
  th, td { border: 1px solid #ccc; padding: 9px; text-align: left; vertical-align: top; }
  th { background: #17365d; color: white; }
  tr:nth-child(even) { background: #f5f7fa; }
  td:nth-child(7) { min-width: 300px; white-space: pre-wrap; }
</style>
</head>
<body>
  <h1>Relatório de e-mails dos clientes</h1>
  <div class="resumo">
    <strong>Total de clientes:</strong> ${emails.length}
    &nbsp; | &nbsp;
    <strong>Prontos para envio:</strong> ${emails.filter(e => e.prontoParaEnvio).length}
    &nbsp; | &nbsp;
    <strong>Revisar:</strong> ${emails.filter(e => !e.prontoParaEnvio).length}
  </div>
  <div class="tabela">
    <table>
      <thead>
        <tr>
          <th>Nº</th><th>Nome</th><th>E-mail</th>
          <th>Perfil</th><th>Saldo</th><th>Assunto</th>
          <th>Mensagem</th><th>Status</th>
        </tr>
      </thead>
      <tbody>${linhas}</tbody>
    </table>
  </div>
</body>
</html>
`;

// Retorna a tabela e a lista de e-mails em um único item.
// Use a saída "emails" para conferir os destinatários.
// Para enviar um por vez, use o node seguinte para dividir a lista.
return [{
  json: {
    totalClientes: emails.length,
    prontosParaEnvio: emails.filter(e => e.prontoParaEnvio).length,
    precisamRevisao: emails.filter(e => !e.prontoParaEnvio).length,
    emails,
    tabelaHTML
  }
}];
